  "20–5000 karakter": { de: "20–5000 Zeichen", fr: "20 à 5000 caractères", en: "20–5000 characters", ar: "20–5000 حرف", fa: "۲۰ تا ۵۰۰۰ نویسه", ru: "20–5000 символов", nl: "20–5000 tekens" },
  "Gayrimenkul tipi, ör. daire, villa, mustakil, arsa, ticari": { de: "Immobilientyp, z. B. daire, villa, mustakil, arsa, ticari", fr: "Type de bien, p. ex. daire, villa, mustakil, arsa, ticari", en: "Property type, e.g. daire, villa, mustakil, arsa, ticari", ar: "نوع العقار، مثل daire وvilla وmustakil وarsa وticari", fa: "نوع ملک، مثلاً daire، villa، mustakil، arsa، ticari", ru: "Тип объекта, напр. daire, villa, mustakil, arsa, ticari", nl: "Type woning, bijv. daire, villa, mustakil, arsa, ticari" },
  "Pozitif sayı; para birimi TRY, EUR, USD veya GBP (varsayılan TRY)": { de: "Positive Zahl; Währung TRY, EUR, USD oder GBP (Standard TRY)", fr: "Nombre positif ; devise TRY, EUR, USD ou GBP (TRY par défaut)", en: "Positive number; currency TRY, EUR, USD or GBP (default TRY)", ar: "رقم موجب؛ العملة TRY أو EUR أو USD أو GBP (الافتراضية TRY)", fa: "عدد مثبت؛ واحد پول TRY، EUR، USD یا GBP (پیش‌فرض TRY)", ru: "Положительное число; валюта TRY, EUR, USD или GBP (по умолчанию TRY)", nl: "Positief getal; valuta TRY, EUR, USD of GBP (standaard TRY)" },
  "Türkiye il ve ilçe adı": { de: "Name der türkischen Provinz und des Bezirks", fr: "Nom de la province et du district en Turquie", en: "Name of the province and district in Türkiye", ar: "اسم المحافظة والمنطقة في تركيا", fa: "نام استان و شهرستان در ترکیه", ru: "Название провинции и района в Турции", nl: "Naam van de provincie en het district in Turkije" },
  "Mahalle adı; aynı adlı mahallelerde posta kodu gerekir": { de: "Name des Viertels; bei gleichnamigen Vierteln ist die Postleitzahl nötig", fr: "Nom du quartier ; code postal requis pour les quartiers homonymes", en: "Neighbourhood name; a postcode is required where names repeat", ar: "اسم الحي؛ يلزم الرمز البريدي للأحياء التي تحمل الاسم نفسه", fa: "نام محله؛ برای محله‌های هم‌نام کد پستی لازم است", ru: "Название квартала; для одноимённых кварталов нужен почтовый индекс", nl: "Naam van de wijk; bij wijken met dezelfde naam is de postcode nodig" },
  "Brüt alan, m², tam sayı": { de: "Bruttofläche, m², ganze Zahl", fr: "Surface brute, m², nombre entier", en: "Gross area, m², whole number", ar: "المساحة الإجمالية، م²، عدد صحيح", fa: "متراژ ناخالص، متر مربع، عدد صحیح", ru: "Общая площадь, м², целое число", nl: "Bruto-oppervlakte, m², geheel getal" },
